var data = JSON.parse(value);
var online = Number(data.summary && data.summary.online);
var total = Number(data.summary && data.summary.total);
if (!isFinite(online) || !isFinite(total)) {
    throw 'summary.online or summary.total is missing';
}
return online + ' of ' + total;

// TRASSIR_NETWORK_NORMALIZE
var v = Number(value);
if (v === 0) return 1;
if (v === 1) return 0;
return -1;

item.params:
var p = JSON.parse(value);

function trimSlash(s) {
    return String(s).replace(/\/+$/, '');
}

function clean(s, maxLen) {
    return String(s || '')
        .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
        .substring(0, maxLen || 2000);
}

function getJson(url) {
    var req = new HttpRequest();
    var body = req.get(url);
    var status = req.getStatus();

    if (status < 200 || status >= 300) {
        throw 'HTTP ' + status + ' for ' + url + ': ' + clean(body, 500);
    }

    try {
        return JSON.parse(body);
    }
    catch (e) {
        throw 'Invalid JSON from ' + url + ': ' + clean(body, 500);
    }
}

function auth(base, path, password) {
    return base + path + (path.indexOf('?') === -1 ? '?' : '&')
        + 'password=' + encodeURIComponent(password);
}

var base = trimSlash(p.base_url);
var password = String(p.password || '');

var out = {
    health: {},
    channels: [],
    summary: {
        total: 0,
        online: 0,
        offline: 0,
        availability: 0
    },
    errors: []
};

try {
    if (password === '') {
        throw 'SDK password is empty';
    }

    out.health = getJson(auth(base, '/health', password));
    var objects = getJson(auth(base, '/objects/', password));

    var localPrefix = '';

    for (var i = 0; i < objects.length; i++) {
        if (String(objects[i]['class']) === 'IP Device' && objects[i].parent) {
            var parent = String(objects[i].parent);

            if (parent.charAt(parent.length - 1) === 'I') {
                localPrefix = parent.substring(0, parent.length - 1);
                break;
            }
        }
    }

    if (localPrefix === '') {
        throw 'Cannot determine local server root from /objects/';
    }

    var localChannelsParent = localPrefix + 'C';

    for (var j = 0; j < objects.length; j++) {
        var o = objects[j];

        if (
            String(o['class']) === 'Channel'
            && String(o.parent) === localChannelsParent
            && o.guid
        ) {
            out.channels.push({
                guid: String(o.guid),
                name: clean(o.name || o.guid, 512),
                parent: String(o.parent || ''),
                class_name: String(o['class'] || '')
            });
        }
    }

    out.summary.total = out.channels.length;

    var healthOnline = Number(out.health.channels_online);
    var healthTotal = Number(out.health.channels_total);

    if (isFinite(healthOnline)) {
        out.summary.online = healthOnline;
    }

    if (isFinite(healthTotal) && healthTotal >= out.summary.online) {
        out.summary.offline = healthTotal - out.summary.online;
        out.summary.availability = healthTotal > 0
            ? Math.round(out.summary.online * 10000 / healthTotal) / 100
            : 0;
    }
}
catch (e) {
    out.errors.push(clean(e, 2000));
}

return JSON.stringify(out);

var p = JSON.parse(value);

function trimSlash(s) {
    return String(s).replace(/\/+$/, '');
}

function clean(s, maxLen) {
    return String(s || '')
        .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
        .substring(0, maxLen || 2000);
}

function getJson(url) {
    var req = new HttpRequest();
    var body = req.get(url);
    var status = req.getStatus();

    if (status < 200 || status >= 300) {
        throw 'HTTP ' + status + ': ' + clean(body, 500);
    }

    return JSON.parse(body);
}

function url(base, path, password) {
    return base + path + (path.indexOf('?') === -1 ? '?' : '&')
        + 'password=' + encodeURIComponent(password);
}

function read(base, path, password, fallback) {
    try {
        var data = getJson(url(base, path, password));
        return typeof data.value !== 'undefined' ? data.value : fallback;
    }
    catch (e) {
        return fallback;
    }
}

var base = trimSlash(p.base_url);
var password = String(p.password || '');
var out = {disks: [], errors: []};

try {
    var root = getJson(url(base, '/settings/archive/', password));
    var names = Array.isArray(root.subdirs) ? root.subdirs : [];

    for (var i = 0; i < names.length; i++) {
        var id = String(names[i]);
        var path = '/settings/archive/' + encodeURIComponent(id);

        var disk = {
            id: id,
            disk_id: String(read(base, path + '/disk_id', password, id)),
            model: clean(read(base, path + '/model', password, ''), 512),
            serial: clean(read(base, path + '/serial', password, ''), 512),
            capacity_gb: Number(read(base, path + '/capacity_gb', password, 0)),
            enable: Number(read(base, path + '/enable', password, 0)),
            unusable: Number(read(base, path + '/unusable', password, 0)),
            read_only: Number(read(base, path + '/read_only', password, 0)),
            forever_read_only: Number(read(base, path + '/forever_read_only', password, 0)),
            format_needed: Number(read(base, path + '/format_needed', password, 0)),
            fsck_in_progress: Number(read(base, path + '/fsck_in_progress', password, 0)),
            system_drive: Number(read(base, path + '/system_drive', password, 0)),
            autodetected: Number(read(base, path + '/autodetected', password, 0)),
            archive_size_days: Number(read(base, path + '/stats/archive_size_days', password, -1)),
            sync_mode: Number(read(base, path + '/stats/sync_mode', password, -1)),
            disk_write_mbs: Number(read(base, path + '/stats/disk_write_mbs', password, 0)),
            disk_read_mbs: Number(read(base, path + '/stats/disk_read_mbs', password, 0)),
            current_speed_mbs: Number(read(base, path + '/stats/current_speed_mbs', password, 0)),
            unavailable: Number(read(base, path + '/stats/unavailable', password, 0)),
            error_counter: Number(read(base, path + '/stats/error_counter', password, 0)),
            last_error_code: clean(read(base, path + '/stats/last_error_code', password, ''), 1000),
            set_error_code: clean(read(base, path + '/stats/set_error_code', password, ''), 1000)
        };

        out.disks.push(disk);
    }
}
catch (e) {
    out.errors.push(clean(e, 2000));
}

return JSON.stringify(out);

parameters.parameter:
var data = JSON.parse(value);
var rows = Array.isArray(data) ? data : (Array.isArray(data.data) ? data.data : []);
var excluded = {};
String("{$TRASSIR.DISK.EXCLUDE}").split(",").forEach(function(v) {
    v = v.trim().toLowerCase();
    if (v !== "") excluded[v] = true;
});
rows.forEach(function(d) {
    var id = String(d["{#DISK_ID}"] || d["{#ID}"] || "").trim().toLowerCase();
    d["{#DISK.MONITOR}"] = excluded[id] ? "0" : "1";
});
return JSON.stringify(Array.isArray(data) ? rows : {data: rows});

item_prototype.params:
var p = JSON.parse(value);

function trimSlash(s) {
    return String(s).replace(/\/+$/, '');
}

function clean(s, maxLen) {
    return String(s || '')
        .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
        .substring(0, maxLen || 2000);
}

function getJson(url) {
    var req = new HttpRequest();
    var body = req.get(url);
    var status = req.getStatus();

    if (status < 200 || status >= 300) {
        throw 'HTTP ' + status + ': ' + clean(body, 500);
    }

    return JSON.parse(body);
}

function auth(base, path, password) {
    return base + path + (path.indexOf('?') === -1 ? '?' : '&')
        + 'password=' + encodeURIComponent(password);
}

function readValue(base, path, password, fallback) {
    try {
        var data = getJson(auth(base, path, password));

        if (data && typeof data.value !== 'undefined') {
            return data.value;
        }
    }
    catch (e) {
        return fallback;
    }

    return fallback;
}

function num(v, fallback) {
    var n = Number(v);
    return isFinite(n) ? n : fallback;
}

var base = trimSlash(p.base_url);
var password = String(p.password || '');
var guid = String(p.guid || '');
var root = '/settings/channels/' + encodeURIComponent(guid);

var out = {
    guid: guid,
    fps_main: -1,
    fps_ss: -1,
    kbps_main: 0,
    kbps_ss: 0,
    kbps_record: 0,
    record_debt: 0,
    last_error: '',
    signal: -1,
    recording_local: -1,
    recording_hw: -1,
    bitrate_exceeded: 0,
    slow_down: 0,
    mainstream_depth: -1,
    substream_depth: -1,
    gb_per_day: -1,
    forecast_gb_per_day: -1,
    grabber_error: '',
    merge_too_slow: 0,
    status: 0
};

out.fps_main = num(readValue(base, root + '/stats/fps_main', password, -1), -1);
out.fps_ss = num(readValue(base, root + '/stats/fps_ss', password, -1), -1);
out.kbps_main = num(readValue(base, root + '/stats/kbps_main', password, 0), 0);
out.kbps_ss = num(readValue(base, root + '/stats/kbps_ss', password, 0), 0);
out.kbps_record = num(readValue(base, root + '/stats/kbps_hw_merge', password, 0), 0);
out.record_debt = num(readValue(base, root + '/stats/debt_sec_hw_merge', password, 0), 0);
out.last_error = clean(readValue(base, root + '/stats/last_error_hw_merge', password, ''), 2000);

out.signal = num(readValue(base, root + '/flags/signal', password, -1), -1);
out.recording_local = num(readValue(base, root + '/flags/recording_local', password, -1), -1);
out.recording_hw = num(readValue(base, root + '/flags/recording_hw', password, -1), -1);
out.bitrate_exceeded = num(readValue(base, root + '/flags/bitrate_exceeded', password, 0), 0);
out.slow_down = num(readValue(base, root + '/flags/slow_down', password, 0), 0);

out.mainstream_depth = num(readValue(base, root + '/arch_stats/mainstream_depth', password, -1), -1);
out.substream_depth = num(readValue(base, root + '/arch_stats/substream_depth', password, -1), -1);
out.gb_per_day = num(readValue(base, root + '/arch_stats/gb_per_day', password, -1), -1);
out.forecast_gb_per_day = num(readValue(base, root + '/arch_stats/forecast_gb_per_day', password, -1), -1);

out.grabber_error = clean(readValue(base, root + '/info/grabber_error', password, ''), 2000);
out.merge_too_slow = num(readValue(base, root + '/info/merge_too_slow', password, 0), 0);

// TRASSIR already reports the channel's actual signal state.
// Do not calculate online/offline from FPS or bitrate.
out.status = out.signal;

return JSON.stringify(out);
